/** CI recipes, byte for byte equal to the files in examples/ci/. */
export const CI_TEMPLATES = {
  /** examples/ci/github-actions.yml */
  github:
    "# Performance measurement run with playwright-performance-regression (pw-perf).\n# Save as .github/workflows/perf.yml. Runs on pull requests and every night; the report in\n# pw-perf-results/ is uploaded also when the run fails. Exit codes: 0 ok, 2 performance regression,\n# 3 tool or config error.\nname: Performance\n\non:\n  pull_request:\n  schedule:\n    - cron: '0 3 * * *'\n  workflow_dispatch:\n\njobs:\n  perf:\n    runs-on: ubuntu-latest\n    timeout-minutes: 60\n    steps:\n      - uses: actions/checkout@v7\n      - uses: actions/setup-node@v7\n        with:\n          node-version: 22\n          cache: npm\n      - run: npm ci\n      - run: npx playwright install --with-deps chromium\n      - name: Measurement run\n        run: npx pw-perf test\n      - name: Upload the performance report\n        if: always()\n        uses: actions/upload-artifact@v7\n        with:\n          name: pw-perf-results\n          path: pw-perf-results/\n          retention-days: 30\n",
  /** examples/ci/gitlab-ci.yml */
  gitlab:
    '# Performance measurement run with playwright-performance-regression (pw-perf).\n# Include this file from .gitlab-ci.yml. Runs in merge request pipelines and scheduled\n# pipelines; exit code 2 (performance regression) is a soft failure, 3 (tool or config error)\n# fails the job. The report in pw-perf-results/ is kept also when the job fails.\nperf:\n  image: node:22\n  timeout: 1h\n  rules:\n    - if: $CI_PIPELINE_SOURCE == "merge_request_event"\n    - if: $CI_PIPELINE_SOURCE == "schedule"\n  script:\n    - npm ci\n    - npx playwright install --with-deps chromium\n    - npx pw-perf test\n  allow_failure:\n    exit_codes: 2\n  artifacts:\n    when: always\n    paths:\n      - pw-perf-results/\n    expire_in: 30 days\n',
  /** examples/ci/Jenkinsfile */
  jenkins:
    "// Performance measurement run with playwright-performance-regression (pw-perf).\n// Use as the script of a pipeline job, e.g. \"Jenkinsfile.perf\". Exit code 2 (performance\n// regression) marks the build UNSTABLE, 3 (tool or config error) fails it. The report in\n// pw-perf-results/ is archived also when the run fails.\npipeline {\n  agent any\n  options {\n    timeout(time: 60, unit: 'MINUTES')\n  }\n  triggers {\n    cron('H 3 * * *')\n  }\n  stages {\n    stage('Performance') {\n      steps {\n        sh 'npm ci'\n        sh 'npx playwright install --with-deps chromium'\n        script {\n          def code = sh(script: 'npx pw-perf test', returnStatus: true)\n          if (code == 2) {\n            unstable('Performance regression (exit code 2)')\n          } else if (code != 0) {\n            error(\"Measurement run failed with exit code ${code}\")\n          }\n        }\n      }\n    }\n  }\n  post {\n    always {\n      archiveArtifacts artifacts: 'pw-perf-results/**', allowEmptyArchive: true\n    }\n  }\n}\n",
  /** examples/ci/azure-pipelines.yml */
  azure:
    '# Performance measurement run with playwright-performance-regression (pw-perf).\n# Register as its own pipeline, e.g. azure-pipelines.perf.yml. Runs on pull requests and every\n# night. Exit code 2 (performance regression) ends the job as "succeeded with issues", 3 (tool or\n# config error) fails it. The report in pw-perf-results/ is published also when the run fails.\ntrigger: none\n\npr:\n  branches:\n    include:\n      - \'*\'\n\nschedules:\n  - cron: \'0 3 * * *\'\n    displayName: Nightly measurement run\n    branches:\n      include:\n        - main\n    always: true\n\npool:\n  vmImage: ubuntu-latest\n\njobs:\n  - job: perf\n    timeoutInMinutes: 60\n    steps:\n      - task: NodeTool@0\n        inputs:\n          versionSpec: \'22.x\'\n      - script: npm ci\n        displayName: Install dependencies\n      - script: npx playwright install --with-deps chromium\n        displayName: Install Chromium\n      - bash: |\n          code=0\n          npx pw-perf test || code=$?\n          if [ "$code" -eq 2 ]; then\n            echo "##vso[task.complete result=SucceededWithIssues;]Performance regression (exit code 2)"\n            exit 0\n          fi\n          exit $code\n        displayName: Measurement run\n      - publish: pw-perf-results\n        artifact: pw-perf-results\n        condition: always()\n        displayName: Publish the performance report\n',
} as const;
